                          <option value="bird">Bird</option>
                          <option value="rabbit">Rabbit</option>
                          <option value="other">Other</option>
                        </select>
                      </div>

                      {/* Pet Status */}
                      <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                          Pet Status
                        </label>
                        <select
                          value={filterStatus}
                          onChange={(e) => setFilterStatus(e.target.value)}
                          className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                        >
                          <option value="all">All Status</option>
                          <option value="lost">Lost</option>
                          <option value="found">Found</option>
                          <option value="adopted">Adopted</option>
                          <option value="available">
                            Available for Adoption
                          </option>
                        </select>
                      </div>

                      {/* Report Status */}
                      <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                          Report Status
                        </label>
                        <select
                          value={filterReportStatus}
                          onChange={(e) =>
                            setFilterReportStatus(e.target.value)
                          }
                          className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                        >
                          <option value="all">All Reports</option>
                          <option value="accepted">Accepted Only</option>
                          <option value="pending">Pending Only</option>
                          <option value="rejected">Rejected Only</option>
                        </select>
                      </div>

                      {/* Gender */}
                      <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                          Gender
                        </label>
                        <select
                          value={filterGender}
                          onChange={(e) => setFilterGender(e.target.value)}
                          className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                        >
                          <option value="">Any Gender</option>
                          <option value="male">Male</option>
                          <option value="female">Female</option>
                        </select>
                      </div>

                      {/* Breed */}
                      <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                          Breed
                        </label>
                        <input
                          type="text"
                          placeholder="e.g., Labrador, Persian..."
                          value={filterBreed}
                          onChange={(e) => setFilterBreed(e.target.value)}
                          className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                        />
                      </div>

                      {/* Location */}
                      <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                          Location
                        </label>
                        <input
                          type="text"
                          placeholder="City, state, or area..."
                          value={filterLocation}
                          onChange={(e) => setFilterLocation(e.target.value)}
                          className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                        />
                      </div>
                    </div>

                    {/* Search Buttons */}
                    <div className="mt-6 flex gap-3">
                      <button
                        onClick={handleSearch}
                        disabled={searchLoading}
                        className="flex-1 flex items-center justify-center gap-2 px-6 py-3 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        <span className="material-icons">search</span>
                        <span className="font-semibold">
                          {searchLoading ? "Searching..." : "Search Pets"}
                        </span>
                      </button>
                      <button
                        onClick={() => {
                          setSearchQuery("");
                          setFilterType("all");
                          setFilterStatus("all");
                          setFilterGender("");
                          setFilterBreed("");
                          setFilterLocation("");
                          setFilterReportStatus("accepted");
                          setSearchResults([]);
                          setHasSearched(false);
                        }}
                        className="px-6 py-3 bg-gray-200 text-gray-700 dark:text-gray-200 rounded-xl hover:bg-gray-300 transition-all duration-200 font-semibold"
                      >
                        Clear Filters
                      </button>
                    </div>
                  </div>

                  {/* Search Results */}
                  <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-xl p-6">
                    <h3 className="text-2xl font-bold mb-4 text-gray-800 flex items-center gap-2">
                      <span className="material-icons">pets</span>
                      Search Results{" "}
                      {hasSearched && `(${searchResults.length} found)`}
                    </h3>

                    {searchLoading ? (
                      <div className="text-center py-16">
                        <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600"></div>
                        <p className="text-gray-600 mt-4">Searching...</p>
                      </div>
                    ) : hasSearched ? (
                      searchResults.length > 0 ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                          {searchResults.map((pet) => (
                            <div
                              key={pet.id}
                              className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg overflow-hidden hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-gray-100"
                            >
                              <div className="relative h-56 overflow-hidden">
                                <img
                                  src={getImageUrl(pet.image)}
                                  alt={pet.name}
                                  className="w-full h-full object-cover"
                                  onError={(e) => {
                                    e.target.src = "/default-pet.png";
                                  }}
                                />
                                <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                                  <h3 className="text-white font-bold text-lg">
                                    {pet.name || "Unnamed"}
                                  </h3>
                                </div>
                                <div className="absolute top-2 right-2">
                                  <span
                                    className={`px-3 py-1 text-white text-xs font-bold rounded-full shadow-lg ${
                                      pet.status === "lost"
                                        ? "bg-red-600"
                                        : pet.status === "found"
                                        ? "bg-green-600"
                                        : pet.status === "adopted"
                                        ? "bg-purple-600"
                                        : "bg-pink-600"
                                    }`}
                                  >
                                    {pet.status.toUpperCase()}
                                  </span>
                                </div>
                              </div>
                              <div className="p-5 space-y-3">
                                <div
                                  className={`inline-block px-3 py-1 rounded-full text-sm font-semibold ${
                                    pet.status === "lost"
                                      ? "bg-red-100 text-red-700"
                                      : pet.status === "found"
                                      ? "bg-green-100 text-green-700"
                                      : pet.status === "adopted"
                                      ? "bg-purple-100 text-purple-700"
                                      : "bg-pink-100 text-pink-700"
                                  }`}
                                >
                                  {pet.type}
                                </div>
                                <div className="space-y-2">
                                  {pet.breed && (
                                    <span className="block text-gray-700 dark:text-gray-200 text-sm">
                                      <span className="font-semibold">
                                        Breed:
                                      </span>{" "}
                                      {pet.breed}
                                    </span>
                                  )}
                                  {pet.gender && (
                                    <span className="block text-gray-700 dark:text-gray-200 text-sm">
                                      <span className="font-semibold">
                                        Gender:
                                      </span>{" "}
                                      {pet.gender}
                                    </span>
                                  )}
                                  {pet.age !== undefined && (
                                    <span className="block text-gray-700 dark:text-gray-200 text-sm">
                                      <span className="font-semibold">
                                        Age:
                                      </span>{" "}
                                      {pet.age}{" "}
                                      {pet.age === 1 ? "year" : "years"}
                                    </span>
                                  )}
                                  {pet.location && (
                                    <span className="block text-gray-600 dark:text-gray-300 text-sm flex items-center gap-1">
                                      <span className="material-icons text-sm">
                                        location_on
                                      </span>
                                      {pet.location}
                                    </span>
                                  )}
                                </div>
                                <button
                                  onClick={() => viewDetails(pet, "pet")}
                                  className="w-full px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-all font-semibold flex items-center justify-center gap-2"
                                >
                                  <span className="material-icons text-sm">
                                    visibility
                                  </span>
                                  View Details
                                </button>
                              </div>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div className="col-span-full text-center py-16">
                          <span className="text-6xl block mb-4">😔</span>
                          <p className="text-gray-500 text-lg">
                            No pets found matching your criteria
                          </p>
                          <p className="text-gray-400 text-sm mt-2">
                            Try adjusting your filters
                          </p>
                        </div>
                      )
                    ) : (
                      <div className="col-span-full text-center py-16">
                        <span className="text-6xl block mb-4">🔍</span>
                        <p className="text-gray-500 text-lg">
                          Enter search criteria and click "Search Pets" to find
                          pets
                        </p>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Available Pets Section */}
              {activeTab === "available-pets" && (
                <div className="bg-gradient-to-br from-pink-50 to-purple-50 rounded-2xl shadow-xl p-8 border border-pink-100">
                  <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                    <span className="material-icons text-3xl text-pink-600">
                      pets
                    </span>
                    <span className="bg-gradient-to-r from-pink-600 via-purple-600 to-pink-600 bg-clip-text text-transparent">
                      ALL AVAILABLE PETS FOR ADOPTION
                    </span>
                  </h2>

                  <div className="mb-6 flex items-center justify-between bg-white rounded-xl p-4 shadow-md">
                    <div className="flex items-center gap-3">
                      <div className="bg-pink-100 p-3 rounded-full">
                        <span className="material-icons text-pink-600">
                          info
                        </span>
                      </div>
                      <div>
                        <h3 className="font-bold text-gray-800">
                          Available for Adoption
                        </h3>
                        <p className="text-sm text-gray-600 dark:text-gray-300">
                          These pets are ready to find their forever homes
                        </p>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-3xl font-bold text-pink-600">
                        {allAvailablePets.length}
                      </div>
                      <div className="text-sm text-gray-600 dark:text-gray-300">
                        Total Pets
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {allAvailablePets.length > 0 ? (
                      allAvailablePets.map((pet) => (
                        <div
                          key={pet.id}
                          className="bg-white dark:bg-gray-800 rounded-2xl shadow-lg overflow-hidden hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-pink-100"
                        >
                          <div className="relative h-56 overflow-hidden">
                            <img
                              src={getImageUrl(pet.image)}
                              alt={pet.name}
                              className="w-full h-full object-cover"
                              onError={(e) => {
                                e.target.src = "/default-pet.png";
                              }}
                            />
                            <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                              <h3 className="text-white font-bold text-lg">
                                {pet.name || "Unnamed"}
                              </h3>
                            </div>
                            <div className="absolute top-2 right-2">
                              <span className="px-3 py-1 bg-pink-600 text-white text-xs font-bold rounded-full shadow-lg flex items-center gap-1">
                                <span className="material-icons text-xs">
                                  favorite
                                </span>
                                AVAILABLE
                              </span>
                            </div>
                            {pet.is_vaccinated && (
                              <div className="absolute top-2 left-2">
                                <span className="px-2 py-1 bg-green-600 text-white text-xs font-bold rounded-full shadow-lg flex items-center gap-1">
                                  <span className="material-icons text-xs">
                                    verified
                                  </span>
                                  Vaccinated
                                </span>
                              </div>
                            )}
                          </div>
                          <div className="p-5 space-y-3">
                            <div className="inline-block px-3 py-1 bg-pink-100 text-pink-700 rounded-full text-sm font-semibold">
                              {pet.type}
                            </div>
                            <div className="space-y-2">
                              {pet.breed && (
                                <div className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-200">
                                  <span className="material-icons text-sm text-pink-600">
                                    pets
                                  </span>
                                  <span className="font-semibold">Breed:</span>{" "}
                                  {pet.breed}
                                </div>
                              )}
                              {pet.gender && (
                                <div className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-200">
                                  <span className="material-icons text-sm text-pink-600">
                                    {pet.gender === "male" ? "male" : "female"}
                                  </span>
                                  <span className="font-semibold">Gender:</span>{" "}
                                  {pet.gender}
                                </div>
                              )}
                              {pet.age !== undefined && (
                                <div className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-200">
                                  <span className="material-icons text-sm text-pink-600">
                                    cake
                                  </span>
                                  <span className="font-semibold">Age:</span>{" "}
                                  {pet.age} {pet.age === 1 ? "year" : "years"}
                                </div>
                              )}
                              {pet.colour && (
                                <div className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-200">
                                  <span className="material-icons text-sm text-pink-600">
                                    palette
                                  </span>
                                  <span className="font-semibold">Color:</span>{" "}
                                  {pet.colour}
                                </div>
                              )}
                              {pet.weight && (
                                <div className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-200">
                                  <span className="material-icons text-sm text-pink-600">
                                    monitor_weight
                                  </span>
                                  <span className="font-semibold">Weight:</span>{" "}
                                  {pet.weight} kg
                                </div>
                              )}
                              {pet.location && (
                                <div className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-300">
                                  <span className="material-icons text-sm text-pink-600">
                                    location_on
                                  </span>
                                  <span>{pet.location}</span>
                                </div>
                              )}
                              {pet.description && (
                                <div className="mt-3 p-3 bg-pink-50 rounded-lg">
                                  <p className="text-xs text-gray-600 dark:text-gray-300 line-clamp-3">
                                    {pet.description}
                                  </p>
                                </div>
                              )}
                            </div>

                            <div className="flex gap-2 pt-3 border-t border-gray-100">
                              <button
                                onClick={() => viewDetails(pet, "pet")}
                                className="flex-1 px-4 py-2 bg-gradient-to-r from-pink-600 to-purple-600 text-white rounded-lg hover:shadow-lg transition-all font-semibold flex items-center justify-center gap-2"
                              >
                                <span className="material-icons text-sm">
                                  visibility
                                </span>
                                View Details
                              </button>
                            </div>

                            {/* Health & Vaccination Info */}
                            <div className="flex gap-2 pt-2">
                              {pet.is_vaccinated && (
                                <div className="flex items-center gap-1 text-xs text-green-700 bg-green-50 px-2 py-1 rounded-full">
                                  <span className="material-icons text-xs">
                                    check_circle
                                  </span>
                                  Vaccinated
                                </div>
                              )}
                              {!pet.is_diseased && (
                                <div className="flex items-center gap-1 text-xs text-purple-700 bg-purple-50 px-2 py-1 rounded-full">
                                  <span className="material-icons text-xs">
                                    health_and_safety
                                  </span>
                                  Healthy
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="col-span-full text-center py-16">
                        <span className="text-6xl block mb-4">🏠</span>
                        <p className="text-gray-500 text-lg">
                          No pets available for adoption at the moment
                        </p>
                        <p className="text-gray-400 text-sm mt-2">
                          Check back later for new additions
                        </p>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Profile Tab */}
              {activeTab === "profile" && (
                <div className="bg-gradient-to-br from-white to-purple-50 rounded-2xl shadow-xl p-8 border-2 border-purple-200">
                  <div className="flex items-center gap-3 mb-6">
                    <span className="material-icons text-3xl text-purple-600">
                      person
                    </span>
                    <h2 className="text-2xl font-bold bg-gradient-to-r from-purple-600 via-pink-500 to-purple-400 bg-clip-text text-transparent">
                      PROFILE MANAGEMENT
                    </h2>
                  </div>

                  <div className="grid md:grid-cols-3 gap-8">
                    {/* Profile Image Section */}
                    <div className="md:col-span-1 flex flex-col items-center">
                      <div className="relative w-48 h-48 mb-6">
                        {profileImagePreview ? (
                          <img
                            src={profileImagePreview}
                            alt="Profile"
                            className="w-full h-full rounded-full object-cover border-4 border-purple-500 shadow-xl"
                          />
                        ) : (
                          <div className="w-full h-full rounded-full bg-gradient-to-br from-purple-100 to-indigo-100 flex items-center justify-center border-4 border-purple-500 shadow-xl">
                            <span className="material-icons text-6xl text-purple-600">
                              person
                            </span>
                          </div>
                        )}
                      </div>

                      {isEditingProfile && (
                        <div className="w-full">
                          <label
                            htmlFor="profile-image-input"
                            className="flex items-center justify-center gap-2 px-4 py-3 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-xl cursor-pointer hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                          >
                            <span className="material-icons">photo_camera</span>
                            <span className="font-semibold">Change Photo</span>
                          </label>
                          <input
                            id="profile-image-input"
                            type="file"
                            accept="image/*"
                            onChange={handleProfileImageChange}
                            className="hidden"
                          />
                        </div>
                      )}
                    </div>

                    {/* Profile Details Section */}
                    <div className="md:col-span-2">
                      <div className="bg-white dark:bg-gray-800 rounded-2xl p-6 shadow-lg border-2 border-purple-200 mb-6">
                        <div className="flex items-start justify-between mb-6">
                          <div>
                            <h3 className="text-2xl font-bold text-gray-800">
                              {profileData.first_name}{" "}
                              {profileData.last_name || user?.username}
                            </h3>
                            <p className="text-gray-500 mt-1">
                              {profileData.email}
                            </p>
                          </div>

                          {!isEditingProfile ? (
                            <button
                              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                              onClick={() => setIsEditingProfile(true)}
                            >
                              <span className="material-icons text-sm">
                                edit
                              </span>
                              <span className="font-semibold">
                                Edit Profile
                              </span>
                            </button>
                          ) : (
                            <div className="flex gap-2">
                              <button
                                className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-green-500 to-green-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                                onClick={handleProfileSubmit}
                                disabled={submitLoading}
                              >
                                <span className="material-icons text-sm">
                                  save
                                </span>
                                <span className="font-semibold">
                                  {submitLoading ? "Saving..." : "Save"}
                                </span>
                              </button>
                              <button
                                className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-red-500 to-red-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                                onClick={() => {
                                  setIsEditingProfile(false);
                                  setProfileImage(null);
                                  setProfileImagePreview(
                                    getImageUrl(profileData.profile_picture)
                                  );
                                }}
                              >
                                <span className="material-icons text-sm">
                                  cancel
                                </span>
                                <span className="font-semibold">Cancel</span>
                              </button>
                            </div>
                          )}
                        </div>

                        {isEditingProfile ? (
                          <form
                            onSubmit={handleProfileSubmit}
                            className="space-y-4"
                          >
                            <div className="grid md:grid-cols-2 gap-4">
                              <div>
                                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                                  First Name
                                </label>
                                <input
                                  type="text"
                                  name="first_name"
                                  value={profileData.first_name}
                                  onChange={handleProfileInputChange}
                                  placeholder="Enter first name"
                                  className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 outline-none transition-all duration-200"
                                />
                              </div>
                              <div>
                                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                                  Last Name
                                </label>
                                <input
                                  type="text"
                                  name="last_name"
                                  value={profileData.last_name}
                                  onChange={handleProfileInputChange}
                                  placeholder="Enter last name"
                                  className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 outline-none transition-all duration-200"
                                />
                              </div>
                            </div>

                            <div className="grid md:grid-cols-2 gap-4">
                              <div>
                                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                                  Email
                                </label>
                                <input
                                  type="email"
                                  name="email"
                                  value={profileData.email}
                                  onChange={handleProfileInputChange}
                                  placeholder="Enter email address"
                                  className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 outline-none transition-all duration-200"
                                />
                              </div>
                              <div>
                                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                                  Phone Number
                                </label>
                                <input
                                  type="tel"
                                  name="phone_no"
                                  value={profileData.phone_no}
                                  onChange={handleProfileInputChange}
                                  placeholder="Enter phone number"
                                  className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 outline-none transition-all duration-200"
                                />
                              </div>
                            </div>

                            <div className="grid md:grid-cols-2 gap-4">
                              <div>
                                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                                  City
                                </label>
                                <input
                                  type="text"
                                  name="city"
                                  value={profileData.city}
                                  onChange={handleProfileInputChange}
                                  placeholder="Enter city"
                                  className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 outline-none transition-all duration-200"
                                />
                              </div>
                              <div>
                                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                                  State
                                </label>
                                <input
                                  type="text"
                                  name="state"
                                  value={profileData.state}
                                  onChange={handleProfileInputChange}
                                  placeholder="Enter state"
                                  className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 outline-none transition-all duration-200"
                                />
                              </div>
                            </div>

                            <div className="grid md:grid-cols-2 gap-4">
                              <div>
                                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                                  PIN Code
                                </label>
                                <input
                                  type="text"
                                  name="pincode"
                                  value={profileData.pincode}
                                  onChange={handleProfileInputChange}
                                  placeholder="Enter PIN code"
                                  className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 outline-none transition-all duration-200"
                                />
                              </div>
                              <div>
                                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                                  Gender
                                </label>
                                <select
                                  name="gender"
                                  value={profileData.gender}
                                  onChange={handleProfileInputChange}
                                  className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 outline-none transition-all duration-200 bg-white"
                                >
                                  <option value="">Select Gender</option>
                                  <option value="Male">Male</option>
                                  <option value="Female">Female</option>
                                  <option value="Other">Other</option>
                                </select>
                              </div>
                            </div>

                            <div>
                              <label className="block text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">
                                Address
                              </label>
                              <textarea
                                name="address"
                                value={profileData.address}
                                onChange={handleProfileInputChange}
                                placeholder="Enter complete address"
                                rows="3"
                                className="w-full px-4 py-3 rounded-xl border-2 border-purple-200 focus:border-purple-500 focus:ring-2 focus:ring-purple-500/20 outline-none transition-all duration-200 resize-none"
                              />
                            </div>
                          </form>
                        ) : (
                          <div className="grid md:grid-cols-2 gap-4">
                            <div className="p-4 bg-gradient-to-br from-purple-50 to-purple-100 rounded-xl">
                              <span className="text-xs font-bold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}">
                                Phone
                              </span>
                              <p className="text-lg font-semibold text-gray-800 mt-1">
                                {profileData.phone_no || "Not provided"}
                              </p>
                            </div>
                            <div className="p-4 bg-gradient-to-br from-indigo-50 to-indigo-100 rounded-xl">
                              <span className="text-xs font-bold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}">
                                City
                              </span>
                              <p className="text-lg font-semibold text-gray-800 mt-1">
                                {profileData.city || "Not provided"}
                              </p>
                            </div>
                            <div className="p-4 bg-gradient-to-br from-purple-50 to-purple-100 rounded-xl">
                              <span className="text-xs font-bold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}">
                                State
                              </span>
                              <p className="text-lg font-semibold text-gray-800 mt-1">
                                {profileData.state || "Not provided"}
                              </p>
                            </div>
                            <div className="p-4 bg-gradient-to-br from-pink-50 to-pink-100 rounded-xl">
                              <span className="text-xs font-bold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}">
                                PIN Code
                              </span>
                              <p className="text-lg font-semibold text-gray-800 mt-1">
                                {profileData.pincode || "Not provided"}
                              </p>
                            </div>
                            <div className="p-4 bg-gradient-to-br from-yellow-50 to-yellow-100 rounded-xl">
                              <span className="text-xs font-bold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}">
                                Gender
                              </span>
                              <p className="text-lg font-semibold text-gray-800 mt-1">
                                {profileData.gender || "Not provided"}
                              </p>
                            </div>
                            <div className="p-4 bg-gradient-to-br from-indigo-50 to-indigo-100 rounded-xl md:col-span-2">
                              <span className="text-xs font-bold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}">
                                Address
                              </span>
                              <p className="text-lg font-semibold text-gray-800 mt-1">
                                {profileData.address || "Not provided"}
                              </p>
                            </div>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* Notifications Tab */}
              {activeTab === "notifications" && (
                <div className="bg-gradient-to-br from-white to-purple-50 rounded-2xl shadow-xl p-8 border-2 border-purple-200">
                  <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                    <span className="material-icons text-3xl text-purple-600">
                      notifications
                    </span>
                    <span className="bg-gradient-to-r from-purple-600 via-pink-500 to-purple-400 bg-clip-text text-transparent">
                      NOTIFICATIONS
                    </span>
                  </h2>
                  <div className="space-y-3">
                    {notifications.length === 0 ? (
                      <div className="text-center py-12">
                        <div className="text-6xl mb-4">🔕</div>
                        <p className="text-gray-500 text-lg">
                          No notifications yet
                        </p>
                      </div>
                    ) : (
                      notifications.map((notification) => (
                        <div
                          key={notification.id}
                          className={`p-4 rounded-xl border-l-4 transition-all duration-200 hover:shadow-md cursor-pointer ${
                            notification.is_read
                              ? "bg-gray-50 border-gray-300"
                              : "bg-purple-50 border-purple-500 shadow-sm"
                          }`}
                          onClick={() => handleNotificationClick(notification)}
                        >
                          <div className="flex items-start justify-between gap-4">
                            <div className="flex-1">
                              <p
                                className={`text-sm ${
                                  notification.is_read
                                    ? "text-gray-600"
                                    : "text-gray-800 font-bold"
                                }`}
                              >
                                {notification.message}
                              </p>
                            </div>
                            <div className="text-xs text-gray-500 dark:text-gray-400 whitespace-nowrap">
                              {new Date(
                                notification.created_at
                              ).toLocaleDateString()}
                            </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              )}
            </main>
          </div>
        </div>

        {/* Pet/Report Detail Modal */}
        {showDetailModal && selectedItem && (
          <div
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fadeIn"
            onClick={() => setShowDetailModal(false)}
          >
            <div
              className="bg-white dark:bg-gray-800 rounded-3xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-y-auto relative animate-slideUp"
              onClick={(e) => e.stopPropagation()}
            >
              {/* Close Button */}
              <button
                onClick={() => setShowDetailModal(false)}
                className="absolute top-4 right-4 z-10 bg-white/90 hover:bg-red-500 text-gray-600 dark:text-gray-300 hover:text-white rounded-full p-2 shadow-lg transition-all duration-300 transform hover:scale-110"
              >
                <span className="material-icons">close</span>
              </button>

              <div className="p-8">
                {/* For adoption requests, use pet data from selectedItem.pet */}
                {(() => {
                  const pet =
                    modalType === "adoption-request" && selectedItem.pet
                      ? selectedItem.pet
                      : selectedItem;
                  return (
                    <>
                      {/* Header Section with Image */}
                      <div className="flex flex-col md:flex-row gap-6 mb-6">
                        {/* Pet/Report Image */}
                        <div className="md:w-1/2">
                          <div className="relative rounded-2xl overflow-hidden shadow-xl">
                            <img
                              src={getImageUrl(pet.image || pet.pet_image)}
                              alt={pet.name || pet.pet_name || "Pet"}
                              className="w-full h-96 object-cover"
                              onError={(e) => {
                                e.target.src = "/default-pet.png";
                              }}
                            />
                            <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                              <h2 className="text-3xl font-bold text-white">
                                {pet.name || pet.pet_name || "Pet Details"}
                              </h2>
                            </div>
                          </div>
                        </div>

                        {/* Quick Info */}
                        <div className="md:w-1/2 space-y-4">
                          <div className="inline-block px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-full text-sm font-semibold shadow-lg">
                            {pet.type || pet.animal_type || "Pet"}
                          </div>

                          <div className="grid grid-cols-2 gap-4">
                            {pet.breed && (
                              <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-4 rounded-xl">
                                <span className="text-xs text-gray-600 dark:text-gray-300 font-semibold">
                                  BREED
                                </span>
                                <p className="text-lg font-bold text-gray-800">
                                  {pet.breed}
                                </p>
                              </div>
                            )}
                            {pet.age && (
                              <div className="bg-gradient-to-br from-indigo-50 to-indigo-100 p-4 rounded-xl">
                                <span className="text-xs text-gray-600 dark:text-gray-300 font-semibold">
                                  AGE
                                </span>
                                <p className="text-lg font-bold text-gray-800">
                                  {pet.age} years
                                </p>
                              </div>
                            )}
                            {pet.gender && (
                              <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-4 rounded-xl">
                                <span className="text-xs text-gray-600 dark:text-gray-300 font-semibold">
                                  GENDER
                                </span>
                                <p className="text-lg font-bold text-gray-800">
                                  {pet.gender}
                                </p>
                              </div>
                            )}
                            {(pet.colour || pet.color) && (
                              <div className="bg-gradient-to-br from-pink-50 to-pink-100 p-4 rounded-xl">
                                <span className="text-xs text-gray-600 dark:text-gray-300 font-semibold">
                                  COLOR
                                </span>
                                <p className="text-lg font-bold text-gray-800">
                                  {pet.colour || pet.color}
                                </p>
                              </div>
                            )}
                          </div>

                          {pet.status && (
                            <div
                              className={`px-4 py-3 rounded-xl text-center font-semibold ${
                                pet.status === "available"
                                  ? "bg-green-100 text-green-700"
                                  : pet.status === "adopted"
                                  ? "bg-purple-100 text-purple-700"
                                  : pet.status === "lost"
                                  ? "bg-red-100 text-red-700"
                                  : "bg-gray-100 text-gray-700 dark:text-gray-200"
                              }`}
                            >
                              {pet.status?.toUpperCase()}
                            </div>
                          )}
                        </div>
                      </div>

                      {/* Description */}
                      {pet.description && (
                        <div className="mb-6 bg-gradient-to-br from-white to-purple-50 p-6 rounded-2xl border-2 border-purple-200">
                          <h3 className="text-xl font-bold text-gray-800 mb-3 flex items-center gap-2">
                            <span className="material-icons text-purple-600">
                              description
                            </span>
                            Description
                          </h3>
                          <p className="text-gray-700 leading-relaxed">
                            {pet.description}
                          </p>
                        </div>
                      )}

                      {/* Location Info */}
                      {(pet.location || pet.pet_location) && (
                        <div className="mb-6 bg-gradient-to-br from-white to-purple-50 p-6 rounded-2xl border-2 border-purple-200">
                          <h3 className="text-xl font-bold text-gray-800 mb-3 flex items-center gap-2">
                            <span className="material-icons text-indigo-600">
                              location_on
                            </span>
                            Location Details
                          </h3>
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            <div>
                              <span className="text-sm text-gray-600 dark:text-gray-300 font-semibold">
                                Location
                              </span>
                              <p className="text-gray-800">
                                {pet.location ||
                                  pet.pet_location ||
                                  "Not specified"}
                              </p>
                            </div>
                            {pet.city && (
                              <div>
                                <span className="text-sm text-gray-600 dark:text-gray-300 font-semibold">
                                  City
                                </span>
                                <p className="text-gray-800">{pet.city}</p>
                              </div>
                            )}
                            {pet.state && (
                              <div>
                                <span className="text-sm text-gray-600 dark:text-gray-300 font-semibold">
                                  State
                                </span>
                                <p className="text-gray-800">{pet.state}</p>
                              </div>
                            )}
                          </div>
                        </div>
                      )}

                      {/* Report Status (for reports) */}
                      {selectedItem.report_status && (
                        <div className="mb-6 bg-gradient-to-br from-yellow-50 to-yellow-100 p-6 rounded-2xl border border-yellow-200">
                          <h3 className="text-xl font-bold text-gray-800 mb-3 flex items-center gap-2">
                            <span className="material-icons text-yellow-600">
                              report
                            </span>
                            Report Status
                          </h3>
                          <span
                            className={`inline-block px-4 py-2 rounded-full text-sm font-semibold ${
                              selectedItem.report_status === "accepted"
                                ? "bg-green-100 text-green-700"
                                : selectedItem.report_status === "pending"
                                ? "bg-yellow-100 text-yellow-700"
                                : "bg-red-100 text-red-700"
                            }`}
                          >
                            {selectedItem.report_status?.toUpperCase()}
                          </span>
                          {selectedItem.user_name && (
                            <p className="text-sm text-gray-600 dark:text-gray-300 mt-3">
                              Reported by: {selectedItem.user_name}
                            </p>
                          )}
                        </div>
                      )}

                      {/* Medical Info */}
                      {(selectedItem.is_vaccinated !== undefined ||
                        selectedItem.is_diseased !== undefined) && (
                        <div className="mb-6 bg-gradient-to-br from-green-50 to-green-100 p-6 rounded-2xl border border-green-200">
                          <h3 className="text-xl font-bold text-gray-800 mb-3 flex items-center gap-2">
                            <span className="material-icons text-green-600">
                              medical_services
                            </span>
                            Medical Information
                          </h3>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {selectedItem.is_vaccinated !== undefined && (
                              <div className="bg-white dark:bg-gray-800 p-4 rounded-xl">
                                <span className="text-sm text-gray-600 dark:text-gray-300 font-semibold">
                                  Vaccination Status
                                </span>
                                <p className="text-gray-800 flex items-center gap-2 mt-1">
                                  {selectedItem.is_vaccinated ? (
                                    <>
                                      <span className="material-icons text-green-600">
                                        check_circle
                                      </span>
                                      Vaccinated
                                    </>
                                  ) : (
                                    <>
                                      <span className="material-icons text-red-600">
                                        cancel
                                      </span>
                                      Not Vaccinated
                                    </>
                                  )}
                                </p>
                              </div>
                            )}
                            {selectedItem.is_diseased !== undefined && (
                              <div className="bg-white dark:bg-gray-800 p-4 rounded-xl">
                                <span className="text-sm text-gray-600 dark:text-gray-300 font-semibold">
                                  Health Status
                                </span>
                                <p className="text-gray-800 flex items-center gap-2 mt-1">
                                  {selectedItem.is_diseased ? (
                                    <>
                                      <span className="material-icons text-orange-600">
                                        warning
                                      </span>
                                      Has Health Condition
                                    </>
                                  ) : (
                                    <>
                                      <span className="material-icons text-green-600">
                                        check_circle
                                      </span>
                                      Healthy
                                    </>
                                  )}
                                </p>
                              </div>
                            )}
                          </div>
                        </div>
                      )}

                      {/* Action Buttons */}
                      <div className="flex gap-4 mt-6">
                        <button
                          onClick={() => setShowDetailModal(false)}
                          className="flex-1 px-6 py-3 bg-gradient-to-r from-gray-500 to-gray-600 text-white font-semibold rounded-xl hover:shadow-xl transform hover:scale-105 transition-all duration-300"
                        >
                          Close
                        </button>
                      </div>
                    </>
                  );
                })()}
              </div>
            </div>
          </div>
        )}

        {/* Notification Detail Modal */}
        {showNotificationModal && selectedNotification && (
          <div
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] flex items-center justify-center p-4 animate-fadeIn"
            onClick={() => setShowNotificationModal(false)}
          >
            <div
              className="bg-gradient-to-br from-white to-purple-50 rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-hidden border-2 border-purple-200 animate-slideUp"
              onClick={(e) => e.stopPropagation()}
            >
              {/* Modal Header */}
              <div className="bg-gradient-to-r from-purple-600 to-indigo-600 p-6 border-b border-purple-200">
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <span className="material-icons text-white text-3xl">
                      notifications_active
                    </span>
                    <h2 className="text-2xl font-bold text-white">
                      Notification Details
                    </h2>
                  </div>
                  <button
                    onClick={() => setShowNotificationModal(false)}
                    className="p-2 hover:bg-white/20 rounded-full transition-colors"
                  >
                    <span className="material-icons text-white">close</span>
                  </button>
                </div>
              </div>

              {/* Modal Content */}
              <div className="p-6 overflow-y-auto max-h-[calc(90vh-120px)]">
                <div className="space-y-6">
                  {/* Notification Status */}
                  <div className="flex items-center gap-2">
                    <span
                      className={`px-4 py-2 rounded-full text-sm font-semibold ${
                        selectedNotification.is_read
                          ? "bg-gray-200 text-gray-700 dark:text-gray-200"
                          : "bg-purple-500 text-white"
                      }`}
                    >
                      {selectedNotification.is_read ? "Read" : "Unread"}
                    </span>
                    <span className="text-sm text-gray-500 dark:text-gray-400">
                      {new Date(
                        selectedNotification.created_at
                      ).toLocaleString()}
                    </span>
                  </div>

                  {/* Notification Title (if exists) */}
                  {selectedNotification.title && (
                    <div className="bg-white dark:bg-gray-800 rounded-xl p-4 border-2 border-purple-200 shadow-sm">
                      <h3 className="text-xl font-bold text-gray-800 flex items-center gap-2">
                        <span className="material-icons text-purple-600">
                          title
                        </span>
                        {selectedNotification.title}
                      </h3>
                    </div>
                  )}

                  {/* Notification Message */}
                  <div className="bg-white dark:bg-gray-800 rounded-xl p-6 border-2 border-purple-200 shadow-sm">
                    <h4 className="text-sm font-semibold uppercase tracking-wide ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mb-3 flex items-center gap-2">
                      <span className="material-icons text-purple-600 text-sm">
                        message
                      </span>
                      Message
                    </h4>
                    <p className="text-gray-800 text-lg leading-relaxed whitespace-pre-wrap">
                      {selectedNotification.message}
                    </p>
                  </div>

                  {/* Additional Info (if exists) */}
                  {selectedNotification.notification_type && (
                    <div className="bg-gradient-to-br from-purple-50 to-indigo-50 rounded-xl p-4 border-2 border-purple-200">
                      <div className="flex items-center gap-2">
                        <span className="material-icons text-purple-600">
                          info
                        </span>
                        <span className="text-sm font-semibold text-gray-700 dark:text-gray-200">
                          Type:
                        </span>
                        <span className="text-sm text-gray-600 dark:text-gray-300">
                          {selectedNotification.notification_type}
                        </span>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* Modal Footer */}
              <div className="bg-purple-50 p-4 border-t border-purple-200 flex justify-end gap-3">
                <button
                  onClick={() => setShowNotificationModal(false)}
                  className="px-6 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white font-semibold rounded-xl hover:shadow-lg transition-all duration-200 flex items-center gap-2"
                >
                  <span className="material-icons text-sm">check</span>
                  Close
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminDashboard;
